action.command:
node -e "
const { execSync } = require('child_process');
let passed = true;
// Secret scan using trufflehog or gitleaks if available, otherwise regex fallback
try {
  execSync('gitleaks detect --staged --no-git -s . 2>&1', {stdio:'pipe'});
} catch(e) {
  // Regex fallback: scan staged diff for obvious secrets
  try {
    const diff = execSync('git diff --cached', {stdio:'pipe'}).toString();
    const secretPatterns = [
      /AKIA[0-9A-Z]{16}/,          // AWS access key
      /sk-[a-zA-Z0-9]{48}/,         // OpenAI key
      /sk-ant-[a-zA-Z0-9\-_]{90,}/, // Anthropic key
      /password\s*=\s*['\"][^'\"]{8,}/i,
      /secret\s*=\s*['\"][^'\"]{8,}/i,
    ];
    for (const p of secretPatterns) {
      if (p.test(diff)) { process.stderr.write('BLOCKED: Potential secret detected in staged changes. Run: git diff --cached | grep -i secret\n'); passed = false; break; }
    }
  } catch(_) {}
}
// Dependency vulnerability check
try {
  execSync('pip-audit --require-hashes -r backend/requirements.txt 2>&1', {stdio:'pipe'});
} catch(e) {
  process.stderr.write('WARNING: pip-audit found issues: ' + (e.stdout || '').toString().substring(0, 500) + '\n');
}
try {
  execSync('npm audit --audit-level=critical --prefix frontend 2>&1', {stdio:'pipe'});
} catch(e) {
  process.stderr.write('WARNING: npm audit found critical issues\n');
}
if (!passed) process.exit(2);
console.log('Pre-commit security checks passed.');
"
